namespace sv_6422e0d6958c48dd9fb2f5c747373402;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

namespace sv_6422e0d6958c48dd9fb2f5c747373402.Services;

public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new(
        "Jane Doe",
        "jane.doe@example.com",
        "https://i.pravatar.cc/150?img=47",
        "Full-stack developer who loves Blazor and open source.");

    private NotificationPrefs _notificationPrefs = new(
        EmailNotifications: true,
        PushNotifications: true,
        WeeklyDigest: false,
        MutedChannels: ["Random"]);

    private SecuritySettings _securitySettings = new(
        TwoFactorEnabled: true,
        LastPasswordChange: DateTime.UtcNow.AddDays(-42),
        Sessions:
        [
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
            new("sess-2", "Safari on iPhone", "New York, US", DateTime.UtcNow.AddHours(-3)),
            new("sess-3", "Firefox on Ubuntu", "London, UK", DateTime.UtcNow.AddDays(-2)),
        ]);

    private AppearanceSettings _appearance = new("System", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() =>
        Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() =>
        Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() =>
        Task.FromResult(_securitySettings);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        if (string.IsNullOrWhiteSpace(currentPassword))
            throw new InvalidOperationException("Current password is required.");

        _securitySettings = _securitySettings with { LastPasswordChange = DateTime.UtcNow };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        var updated = _securitySettings.Sessions
            .Where(s => s.Id != sessionId)
            .ToList();
        _securitySettings = _securitySettings with { Sessions = updated };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() =>
        Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

.sidebar-title {
    padding: 0.5rem 1rem;
    font-weight: 600;
    color: #6c757d;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
}

::deep .nav-link {
    color: #495057;
    border-radius: 0.375rem;
    padding: 0.625rem 1rem;
    margin-bottom: 0.25rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.95rem;
    transition: background-color 0.15s, color 0.15s;
}

::deep .nav-link:hover {
    background-color: #f8f9fa;
    color: #212529;
}

::deep .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.section-icon {
    font-size: 1.1rem;
}

@inject ISettingsService SettingsService

@if (_isLoading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_profile is not null)
{
    <h3 class="mb-4">Profile</h3>

    <div class="avatar-preview mb-4 text-center">
        <img src="@_editAvatarUrl" alt="User avatar" class="rounded-circle border" width="96" height="96" />
        <p class="text-muted small mt-2 mb-0 text-break">@_editAvatarUrl</p>
    </div>

    <div class="mb-3">
        <label class="form-label" for="profileDisplayName">Display Name</label>
        <input id="profileDisplayName" class="form-control" @bind="_editDisplayName" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="profileEmail">Email</label>
        <input id="profileEmail" type="email" class="form-control" @bind="_editEmail" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="profileBio">Bio</label>
        <textarea id="profileBio" class="form-control" rows="4" @bind="_editBio"></textarea>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_isSaving">
            @(_isSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Profile saved successfully!
        </div>
    }
}

@code {
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";
    private bool _isLoading = true;
    private bool _isSaving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateFields();
        _isLoading = false;
    }

    private void PopulateFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editAvatarUrl = _profile.AvatarUrl;
        _editBio = _profile.Bio;
    }

    private async Task SaveAsync()
    {
        _isSaving = true;
        _showSuccess = false;

        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;

        _isSaving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelayAsync();
    }

    private async Task HideSuccessAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        PopulateFields();
        _showSuccess = false;
    }
}

@inject ISettingsService SettingsService

@if (_isLoading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    <h3 class="mb-4">Notifications</h3>

    <div class="mb-4">
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <h5>Muted Channels</h5>
    <div class="channel-list mb-4">
        @foreach (var channel in _availableChannels)
        {
            <div class="form-check mb-1">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@_mutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_isSaving">
        @(_isSaving ? "Saving…" : "Save Preferences")
    </button>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Preferences saved successfully!
        </div>
    }
}

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private readonly HashSet<string> _mutedChannels = [];
    private bool _isLoading = true;
    private bool _isSaving;
    private bool _showSuccess;

    private static readonly string[] _availableChannels =
        ["General", "Announcements", "Engineering", "Design", "Marketing", "Support", "Random"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        foreach (var ch in prefs.MutedChannels) _mutedChannels.Add(ch);
        _isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _isSaving = true;
        _showSuccess = false;

        var updated = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);

        _isSaving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelayAsync();
    }

    private async Task HideSuccessAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@if (Visible)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1" role="dialog" aria-modal="true">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" aria-label="Close"
                            @onclick="OnCancel"></button>
                </div>
                <div class="modal-body">
                    <p>
                        Are you sure you want to revoke the session on
                        <strong>@Session?.Device</strong> from
                        <strong>@Session?.Location</strong>?
                    </p>
                    <p class="text-muted small mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="OnCancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="OnConfirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public bool Visible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter, EditorRequired] public EventCallback OnConfirm { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
}

@inject ISettingsService SettingsService

<div class="card mb-4">
    <button class="card-header d-flex justify-content-between align-items-center border-0 bg-transparent w-100 text-start"
            @onclick="() => _isExpanded = !_isExpanded"
            aria-expanded="@_isExpanded">
        <h5 class="mb-0">Change Password</h5>
        <span>@(_isExpanded ? "▲" : "▼")</span>
    </button>

    @if (_isExpanded)
    {
        <div class="card-body pt-0">
            <div class="mb-3">
