@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private readonly HashSet<string> _mutedChannels = [];
    private bool _isLoading = true;
    private bool _isSaving;
    private bool _showSuccess;

    private static readonly string[] _availableChannels =
        ["General", "Announcements", "Engineering", "Design", "Marketing", "Support", "Random"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        foreach (var ch in prefs.MutedChannels) _mutedChannels.Add(ch);
        _isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _isSaving = true;
        _showSuccess = false;

        var updated = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);

        _isSaving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelayAsync();
    }

    private async Task HideSuccessAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

