</div>

@code {
    private bool _isExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _errorMessage;
    private bool _showSuccess;
    private bool _isUpdating;

    private async Task UpdatePasswordAsync()
    {
        _errorMessage = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _errorMessage = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _errorMessage = "New password and confirmation do not match.";
            return;
        }

        _isUpdating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _isUpdating = false;
        }
    }
}
"}

{"path": "/tmp/sv-6422e0d6958c48dd9fb2f5c747373402/Components/Settings/SecuritySection.razor", "file_text": "@inject ISettingsService SettingsService

@if (_isLoading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_settings is not null)
{
    <h3 class="mb-4">Security</h3>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <p class="text-muted mb-0 small">
                        @if (_twoFactorEnabled)
                        {
                            <span class="badge bg-success me-1">Enabled</span>
                            <text>Your account is protected with 2FA.</text>
                        }
                        else
                        {
                            <span class="badge bg-warning text-dark me-1">Disabled</span>
                            <text>Enable 2FA for additional security.</text>
                        }
                    </p>
                </div>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" id="twoFactor" role="switch"
                           checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
        </div>
    </div>

    @if (_settings.LastPasswordChange.HasValue)
    {
        <p class="text-muted small">
            Last password change: @_settings.LastPasswordChange.Value.ToString("f")
        </p>
    }

    <ActiveSessionsTable Sessions="@_sessions"
                         CurrentSessionId="@_sessions.FirstOrDefault()?.Id"
                         OnSessionRevoked="RevokeSessionAsync" />
}

@code {
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;
    private bool _isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _sessions = [.. _settings.Sessions];
        _isLoading = false;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}
"}

{"path": "/tmp/sv-6422e0d6958c48dd9fb2f5c747373402/Components/Settings/AppearanceSection.razor", "file_text": "@inject ISettingsService SettingsService

@if (_isLoading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    <h3 class="mb-4">Appearance</h3>

    <div class="mb-4">
        <h5>Theme</h5>
        @foreach (var t in _themes)
        {
            <div class="form-check form-check-inline">
                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                       value="@t" checked="@(_theme == t)" @onchange="() => _theme = t" />
                <label class="form-check-label" for="@($"theme-{t}")">@t</label>
            </div>
        }
    </div>

    <div class="mb-4">
        <h5>Font Size</h5>
        @foreach (var s in _fontSizes)
        {
            <div class="form-check form-check-inline">
                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                       value="@s" checked="@(_fontSize == s)" @onchange="() => _fontSize = s" />
                <label class="form-check-label" for="@($"fs-{s}")">@s</label>
            </div>
        }
    </div>

    <div class="mb-4">
        <h5>Language</h5>
        <select class="form-select" style="max-width: 300px;" @bind="_language">
            @foreach (var lang in _languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header">
            <h5 class="mb-0">Preview</h5>
        </div>
        <div class="card-body @PreviewThemeClass" style="@PreviewStyles">
            <h6>Sample Heading</h6>
            <p class="mb-2">This is how your content will look with the selected settings.</p>
            <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_isSaving">
        @(_isSaving ? "Saving…" : "Save")
    </button>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Appearance settings saved!
        </div>
    }
}

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _isLoading = true;
    private bool _isSaving;
    private bool _showSuccess;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    private string PreviewThemeClass => _theme == "Dark" ? "text-light" : "";

    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-primary";

    private string PreviewStyles
    {
        get
        {
            var bg = _theme == "Dark" ? "background-color:#1e1e1e;" : "background-color:#ffffff; border: 1px solid #dee2e6;";
            var fs = _fontSize switch
            {
                "Small" => "font-size:0.85rem;",
                "Large" => "font-size:1.25rem;",
                _ => "font-size:1rem;",
            };
            var pad = _compactMode ? "padding:0.5rem;" : "padding:1.25rem;";
            return $"{bg}{fs}{pad}border-radius:0.375rem;transition:all 0.2s ease;";
        }
    }

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _isLoading = false;
    }

    private async Task SaveAsync()
    {
        _isSaving = true;
        _showSuccess = false;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _isSaving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelayAsync();
    }

    private async Task HideSuccessAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

