toolArgs.file_text:
@if (Visible)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1" role="dialog" aria-modal="true">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" aria-label="Close"
                            @onclick="OnCancel"></button>
                </div>
                <div class="modal-body">
                    <p>
                        Are you sure you want to revoke the session on
                        <strong>@Session?.Device</strong> from
                        <strong>@Session?.Location</strong>?
                    </p>
                    <p class="text-muted small mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="OnCancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="OnConfirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public bool Visible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter, EditorRequired] public EventCallback OnConfirm { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
}

@inject ISettingsService SettingsService

<div class="card mb-4">
    <button class="card-header d-flex justify-content-between align-items-center border-0 bg-transparent w-100 text-start"
            @onclick="() => _isExpanded = !_isExpanded"
            aria-expanded="@_isExpanded">
        <h5 class="mb-0">Change Password</h5>
        <span>@(_isExpanded ? "▲" : "▼")</span>
    </button>

    @if (_isExpanded)
    {
        <div class="card-body pt-0">
            <div class="mb-3">
                <label class="form-label" for="currentPwd">Current Password</label>
                <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="newPwd">New Password</label>
                <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="confirmPwd">Confirm New Password</label>
                <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">@_errorMessage</div>
            }
            @if (_showSuccess)
            {
                <div class="alert alert-success" role="alert">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_isUpdating">
                @(_isUpdating ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _isExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _errorMessage;
    private bool _showSuccess;
    private bool _isUpdating;

    private async Task UpdatePasswordAsync()
    {
        _errorMessage = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _errorMessage = "All password fields are required.";
            return;
        }

