@inject ISettingsService SettingsService

@if (_isLoading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_settings is not null)
{
    <h3 class="mb-4">Security</h3>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <p class="text-muted mb-0 small">
                        @if (_twoFactorEnabled)
                        {
                            <span class="badge bg-success me-1">Enabled</span>
                            <text>Your account is protected with 2FA.</text>
                        }
                        else
                        {
                            <span class="badge bg-warning text-dark me-1">Disabled</span>
                            <text>Enable 2FA for additional security.</text>
                        }
                    </p>
                </div>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" id="twoFactor" role="switch"
                           checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
        </div>
    </div>

    @if (_settings.LastPasswordChange.HasValue)
    {
        <p class="text-muted small">
            Last password change: @_settings.LastPasswordChange.Value.ToString("f")
        </p>
    }

    <ActiveSessionsTable Sessions="@_sessions"
                         CurrentSessionId="@_sessions.FirstOrDefault()?.Id"
                         OnSessionRevoked="RevokeSessionAsync" />
}

@code {
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;
    private bool _isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _sessions = [.. _settings.Sessions];
        _isLoading = false;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}

